import{_ as a,C as r,c as s,o as i,a3 as t,G as n}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Payment terms","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/customer-invoices/payment-terms.md","filePath":"master/finance/customer-invoices/payment-terms.md","lastUpdated":1793074831000}'),l={name:"master/finance/customer-invoices/payment-terms.md"};function m(d,e,h,g,u,c){const o=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="payment-terms" tabindex="-1">Payment terms <a class="header-anchor" href="#payment-terms" aria-label="Permalink to &quot;Payment terms&quot;">​</a></h1><p>A payment term is a rule that says when a customer must pay. For example &quot;pay within 30 days&quot;, or &quot;half now and half in 30 days&quot;. You pick a term on an invoice and Aureus works out the due date for you, so nobody has to count days by hand.</p><blockquote><p><strong>In simple words:</strong> A payment term turns the invoice date into one or more due dates.</p></blockquote><p>Open the list with <code>Invoices → Configurations → Payment Terms</code> or <code>Accounting → Configurations → Invoicing → Payment Terms</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows ready-made terms such as <strong>Immediate Payment</strong>, <strong>15 Days</strong>, <strong>21 Days</strong>, <strong>30 Days</strong>, <strong>45 Days</strong>, <strong>End of Following Month</strong>, <strong>10 Days after End of Next Month</strong>, <strong>2/7 Net 30</strong>, <strong>30% Now, Balance 60 Days</strong> and <strong>90 Days, on the 10th</strong>. Tabs are <strong>All</strong> and <strong>Archived</strong>. Use <strong>Group by</strong> to fold by <strong>Company Name</strong> or filter by <strong>Payment Term</strong>.</p>',6)),n(o,{src:"/images1/finance/payment_term_list.png",alt:"Payment Terms list with the All and Archived tabs and the ready-made terms"}),e[1]||(e[1]=t('<h2 id="create-a-payment-term" tabindex="-1">Create a payment term <a class="header-anchor" href="#create-a-payment-term" aria-label="Permalink to &quot;Create a payment term&quot;">​</a></h2><ol><li>Go to <code>Invoices → Configurations → Payment Terms</code> or <code>Accounting → Configurations → Invoicing → Payment Terms</code>.</li><li>Click <strong>New Payment Term</strong>.</li><li>Fill in the top section, then add the due terms.</li><li>Click <strong>Create</strong>.</li></ol>',2)),n(o,{src:"/images1/finance/payment_term_create.png",alt:"New Payment Term form: name '30 Days', one due term of 100 Percent after 30 days, with the preview on the right"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Payment Term:</em></strong> The name people pick on the invoice. Required. Use a clear name such as &quot;30 Days&quot;.</li><li><strong><em>Company:</em></strong> Limit the term to one company. Leave it on <strong>All Companies</strong> to share it.</li><li><strong><em>Note:</em></strong> Text about the term. Use it to explain the rule to your team.</li></ul><h3 id="due-terms" tabindex="-1">Due Terms <a class="header-anchor" href="#due-terms" aria-label="Permalink to &quot;Due Terms&quot;">​</a></h3><p>A term has one or more due terms. Each due term says how much is due and when. Click <strong>Add Due Term</strong> for each part.</p><ul><li><strong><em>Value:</em></strong> How the amount is counted. Choose <strong>Percent</strong> for a share of the total, or <strong>Fixed</strong> for a fixed amount.</li><li><strong><em>Due:</em></strong> The number. With <strong>Percent</strong>, enter a value from 0 to 100. With <strong>Fixed</strong>, enter the amount.</li><li><strong><em>Delay Type:</em></strong> How the date is counted. Choose one of: <ul><li><strong>Days After:</strong> Counts the days from the invoice date.</li><li><strong>Days After End of Month:</strong> Counts the days from the end of the invoice month.</li><li><strong>Days After End of Next Month:</strong> Counts the days from the end of the month after the invoice month.</li><li><strong>Days End of Month No The:</strong> Adds the days to the invoice date. Then the due date moves to a fixed day of the next month. Use <strong>Days on the next month</strong> to give that day. Enter 0 to land on the end of the month. This is the label as the app shows it.</li></ul></li><li><strong><em>Days:</em></strong> How many days to add.</li><li><strong><em>Days on the next month:</em></strong> The day of the next month, such as 10. It is hidden at first. Use the column toggle to show it.</li></ul><p>The preview on the right shows an example of 1,000.00 and the due dates it would get. Use it to check your rule before you save.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Make the percentages of all due terms add up to 100. If they do not, part of the invoice has no due date.</p></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p><strong>30 days:</strong> One due term. <strong>Value</strong> Percent, <strong>Due</strong> 100, <strong>Delay Type</strong> Days After, <strong>Days</strong> 30. An invoice dated July 1 is due on July 31.</p><p><strong>50 % now, 50 % in 30 days:</strong> Two due terms.</p><ol><li><strong>Percent</strong>, 50, <strong>Days After</strong>, <strong>Days</strong> 0. Half is due on the invoice date.</li><li><strong>Percent</strong>, 50, <strong>Days After</strong>, <strong>Days</strong> 30. The other half is due 30 days later.</li></ol><p><strong>End of the following month:</strong> One due term. <strong>Percent</strong>, 100, <strong>Days After End of Next Month</strong>, <strong>Days</strong> 0.</p><h2 id="use-a-payment-term" tabindex="-1">Use a payment term <a class="header-anchor" href="#use-a-payment-term" aria-label="Permalink to &quot;Use a payment term&quot;">​</a></h2><ul><li>On an invoice, pick it in <strong>Payment Term</strong>. The <strong>Due Date</strong> field then hides and the term gives the date. See <a href="./create-invoice.html">Create an invoice</a>.</li><li>On a customer, set <strong>Payment Terms</strong> in the <strong>Sales and Purchases</strong> tab. Every new invoice for that customer starts with it. See <a href="./../../sales/sales/quotations-orders/manage-customers.html">Manage customers</a>.</li></ul><h2 id="edit-and-delete" tabindex="-1">Edit and delete <a class="header-anchor" href="#edit-and-delete" aria-label="Permalink to &quot;Edit and delete&quot;">​</a></h2><p>Use the row menu to <strong>View</strong>, <strong>Edit</strong> or <strong>Delete</strong>. A deleted term moves to <strong>Archived</strong> and can be restored. A term that is used on journal entries cannot be deleted for good.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-invoice.html">Create an invoice</a></li><li><a href="./../../sales/sales/quotations-orders/manage-customers.html">Manage customers</a></li><li><a href="./../vendor-bills/create-bill.html">Create a vendor bill</a></li></ul>',18))])}const f=a(l,[["render",m]]);export{p as __pageData,f as default};
